//! Memo decisions of the Celestia fork of packet-forward-middleware
//! (celestiaorg/ibc-apps#3), generated by its real `OnRecvPacket` and
//! `OnTimeoutPacket` (`conformance/pfm-fork`), against the Rust code that
//! runs from app version 12.
#![allow(clippy::unwrap_used)]
use serde_json::Value;
use x_packetforward::memo::{self, MAX_FORWARD_MEMO_LENGTH, Pfm, Recv};
use x_packetforward::middleware::{DEFAULT_FORWARD_TIMEOUT_NS, FORK_ERROR_ACK_MESSAGE};

/// The fork commit the fixture was generated from (`conformance/pfm-fork`).
const FORK_COMMIT: &str = "34b056cdd1ea870aa95d8c52ebc9c8032b849afd";

/// Whether the pinned fork commit lacks the 32768-byte limit on forward
/// memos at receive, which celestia-rs already applies. Set to `false`
/// when the oracle is re-pinned to a fork commit that has it.
const RECEIVE_LIMIT_PENDING: bool = true;

fn memo_of(v: &Value) -> String {
    v.as_array()
        .unwrap()
        .iter()
        .map(|p| {
            p["s"]
                .as_str()
                .unwrap()
                .repeat(usize::try_from(p["n"].as_u64().unwrap()).unwrap())
        })
        .collect()
}

fn assert_bytes(got: &str, want: &Value, name: &str) {
    let got = gostr::to_go_bytes(got);
    assert_eq!(got.len() as u64, want["len"].as_u64().unwrap(), "{name}");
    assert_eq!(
        encoding::hex::encode(&hash::sha256(&got)),
        want["sha256"].as_str().unwrap(),
        "{name}"
    );
}

#[test]
fn memo_decisions_match_the_fork() {
    let f: Value = serde_json::from_str(include_str!(
        "../../../../../conformance/fixtures/pfm-fork.json"
    ))
    .unwrap();
    assert_eq!(f["fork_commit"], FORK_COMMIT);
    let error_ack = encoding::hex::encode(
        &x_ibc::router::Acknowledgement::error_string(FORK_ERROR_ACK_MESSAGE).bytes,
    );
    let recv = f["recv"].as_array().unwrap();
    assert!(recv.len() >= 90);
    let mut pending = 0;
    for v in recv {
        let name = v["name"].as_str().unwrap();
        let memo = memo_of(&v["memo"]);
        let got = memo::on_recv(&memo, Pfm::Fork);
        match v["outcome"].as_str().unwrap() {
            "pass" => assert_eq!(got, Recv::NotForward, "{name}"),
            "error" => {
                assert!(matches!(got, Recv::Error(_)), "{name}: {got:?}");
                assert_eq!(v["ack_hex"].as_str().unwrap(), error_ack, "{name}");
            }
            "forward"
                if RECEIVE_LIMIT_PENDING && gostr::go_len(&memo) > MAX_FORWARD_MEMO_LENGTH =>
            {
                assert!(matches!(got, Recv::Error(_)), "{name}: {got:?}");
                pending += 1;
            }
            "forward" => {
                let Recv::Forward(m) = got else {
                    panic!("{name}: {got:?}");
                };
                let fw = &v["forwarded"];
                assert_eq!(fw["receiver"], m.receiver.as_str(), "{name}");
                assert_eq!(fw["port"], m.port.as_str(), "{name}");
                assert_eq!(fw["channel"], m.channel.as_str(), "{name}");
                // Block time 0: the timeout timestamp is the timeout.
                let timeout = if m.timeout <= 0 {
                    DEFAULT_FORWARD_TIMEOUT_NS
                } else {
                    m.timeout
                };
                assert_eq!(
                    fw["timeout_ns"].as_u64(),
                    u64::try_from(timeout).ok(),
                    "{name}"
                );
                assert_eq!(
                    fw["retries"].as_u64(),
                    Some(u64::from(m.retries.unwrap_or(0))),
                    "{name}"
                );
                let next = match m.next {
                    None => String::new(),
                    Some(Ok(s)) => s,
                    Some(Err(e)) => panic!("{name}: {e}"),
                };
                assert_bytes(&next, &fw["memo"], name);
            }
            other => panic!("{name}: {other}"),
        }
    }
    // 32769 and 32770 bytes, with ASCII and with two-byte padding.
    assert_eq!(pending, if RECEIVE_LIMIT_PENDING { 4 } else { 0 });

    let retry = f["retry"].as_array().unwrap();
    assert!(retry.len() >= 13);
    for v in retry {
        let name = v["name"].as_str().unwrap();
        let memo = memo_of(&v["memo"]);
        let next = match memo::retry_next(&memo, Pfm::Fork) {
            Ok(None) => String::new(),
            Ok(Some(Ok(s))) => s,
            other => panic!("{name}: {other:?}"),
        };
        assert_bytes(&next, &v["retried"], name);
    }
}
